config.font = wezterm.font('MonaspiceKr Nerd Font', { weight = 'Regular' })
config.font_size = 12.0

-- UI / Titlebar
config.window_decorations = "RESIZE" -- Minimal decorations
config.window_background_opacity = 0.90
config.window_background_blur_radius = 20

-- Tabs look customization
config.use_fancy_tab_bar = false
config.tab_bar_at_bottom = true
config.hide_tab_bar_if_only_one_tab = true

-- Disguise Titlebar / Background merge
config.window_frame = {
  active_titlebar_bg = '#1d2021',
  inactive_titlebar_bg = '#1d2021',
}

config.colors = {
  tab_bar = {
    background = '#1d2021',
    active_tab = {
      bg_color = '#d79921',
      fg_color = '#1d2021',
    },
    inactive_tab = {
      bg_color = '#3c3836',
      fg_color = '#ebdbb2',
    },
    inactive_tab_hover = {
      bg_color = '#504945',
      fg_color = '#ebdbb2',
    },
    new_tab = {
      bg_color = '#1d2021',
      fg_color = '#ebdbb2',
    },
  }
}

-- Padding
config.window_padding = {
  left = 15,
  right = 15,
  top = 15,
  bottom = 15,
}

-- Keybindings
config.keys = {
  -- Close pane with Ctrl-Q
  {
    key = 'q',
    mods = 'CTRL',
    action = wezterm.action.CloseCurrentPane { confirm = false },
  },
  -- New Tab
  {
    key = 't',
    mods = 'CTRL|SHIFT',
    action = wezterm.action.SpawnTab 'CurrentPaneDomain',
  },
}

return config

