config.font_size = 12.0
config.line_height = 1.4

-- UI
config.window_decorations = "RESIZE"
config.window_background_opacity = 0.90
config.window_frame = {
  active_titlebar_bg = bg,
  inactive_titlebar_bg = bg,
}

-- Initialize tabline plugin
local tabline = wezterm.plugin.require("https://github.com/michaelbrusegard/tabline.wez")

-- Configure tabline for "Pill" look and transparency
tabline.setup({
  options = {
    theme = 'Gruvbox Dark (Gogh)',
    section_separators = {
      left = wezterm.nerdfonts.ple_right_half_circle_thick,
      right = wezterm.nerdfonts.ple_left_half_circle_thick,
    },
    tab_separators = {
      left = wezterm.nerdfonts.ple_right_half_circle_thick,
      right = wezterm.nerdfonts.ple_left_half_circle_thick,
    },
    component_separators = {
      left = wezterm.nerdfonts.ple_right_half_circle_thin,
      right = wezterm.nerdfonts.ple_left_half_circle_thin,
    },
    theme_overrides = {
      tab = {
        active = { fg = '#1d2021', bg = '#d79921' },
        inactive = { fg = '#ebdbb2', bg = '#3c3836' },
      },
    },
  },
  sections = {
    tabline_a = { 'mode' },
    tabline_b = { 'workspace' },
    tabline_c = { ' ' }, -- Spacer
    tabline_x = { 'cpu', 'memory' },
    tabline_y = { 'datetime' },
    tabline_z = { 'hostname' },
  },
})

-- Apply tabline settings
tabline.apply_to_config(config)

-- Manual overrides to ensure transparency and bottom bar
config.use_fancy_tab_bar = false
config.tab_bar_at_bottom = true
config.hide_tab_bar_if_only_one_tab = true
config.colors = {
  tab_bar = {
    background = 'none', -- Force transparency
  }
}

-- Keybindings
config.keys = {
  { key = 'q', mods = 'CTRL', action = wezterm.action.CloseCurrentPane { confirm = false } },
  { key = 't', mods = 'CTRL|SHIFT', action = wezterm.action.SpawnTab 'CurrentPaneDomain' },
}

return config

